CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE TABLE IF NOT EXISTS __energy_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, url text NOT NULL, type text NOT NULL, is_active boolean DEFAULT true, last_success_at timestamptz, last_error text);
CREATE TABLE IF NOT EXISTS outages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, area_name text NOT NULL, addresses_raw text NOT NULL, addresses_normalized text NOT NULL DEFAULT '', reason text, status text NOT NULL DEFAULT 'scheduled', queue integer, source text NOT NULL DEFAULT 'unknown', external_id text, content_hash text NOT NULL, first_seen_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outages_starts_ends_idx ON outages (starts_at, ends_at);
CREATE INDEX IF NOT EXISTS outages_addresses_trgm_idx ON outages USING gist (addresses_normalized gist_trgm_ops);
CREATE UNIQUE INDEX IF NOT EXISTS outages_content_source_idx ON outages (content_hash, source_id);
CREATE INDEX IF NOT EXISTS outages_status_idx ON outages (status);
CREATE INDEX IF NOT EXISTS outages_area_idx ON outages (area_name);
CREATE TABLE IF NOT EXISTS addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL CHECK (type IN ('district','street','settlement')), name_uk text NOT NULL, name_ru text, name_normalized text NOT NULL, parent_id uuid REFERENCES addresses(id) ON DELETE SET NULL, city text, source text NOT NULL DEFAULT 'outage');
CREATE INDEX IF NOT EXISTS addresses_name_uk_trgm_idx ON addresses USING gin (name_uk gin_trgm_ops);
CREATE INDEX IF NOT EXISTS addresses_name_normalized_trgm_idx ON addresses USING gin (name_normalized gin_trgm_ops);
CREATE INDEX IF NOT EXISTS addresses_parent_idx ON addresses (parent_id);
CREATE OR REPLACE FUNCTION energy_normalize_address(input text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT trim(regexp_replace(regexp_replace(translate(lower(unaccent(coalesce(input, ''))), 'ыэёїи', 'иееіі'), '[[:punct:]]+', ' ', 'g'), '^(вулиця|вул|улица|ул|проспект|просп|провулок|пров|переулок|пер|село|с\.?)[[:space:]]+', '', 'i')) $$;
INSERT INTO addresses (type, name_uk, name_normalized, city, source) SELECT DISTINCT 'street', s.name, energy_normalize_address(s.name), o.area_name, 'outage' FROM outages o CROSS JOIN LATERAL regexp_split_to_table(o.addresses_raw, '[;,\\n]+') AS s(name) WHERE length(trim(s.name)) >= 3 ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id), external_id text UNIQUE, source_url text, title text NOT NULL, description text NOT NULL DEFAULT '', started_at timestamptz NOT NULL, eta_at timestamptz, severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS grid_status (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id), level text NOT NULL DEFAULT 'stable', message text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, label text NOT NULL, value text NOT NULL, region text);
CREATE TABLE IF NOT EXISTS parse_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running', records_found integer NOT NULL DEFAULT 0, error_message text, raw_snapshot_ref text);
CREATE INDEX IF NOT EXISTS parse_runs_source_started_idx ON parse_runs (source_id, started_at DESC);
CREATE TABLE IF NOT EXISTS geocode_cache (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), address_query text NOT NULL UNIQUE, lat double precision NOT NULL, lon double precision NOT NULL, cached_at timestamptz NOT NULL DEFAULT now());
